import React from 'react';
import type { Preview, Decorator } from '@storybook/react-webpack5';
import { ChakraProvider } from '@chakra-ui/react';
import { IntlProvider } from 'react-intl';
import theme from '../overrides/app/theme';
import { ZimmTokensGlobal } from '../overrides/app/theme/zimmTokensGlobal';
import { ZimmFontFace } from '../overrides/app/theme/fontFace';
import { CHAKRA_TOAST_A11Y_EXCLUDE } from './a11yExcludes';

// @salesforce/pwa-kit-runtime's browser-side getConfig() (utils/ssr-config.client.js) just
// reads window.__CONFIG__, which the real app's SSR bootstrap script sets and Storybook never
// does — every call site that reads getConfig().app (Zimmermann's own, e.g.
// overrides/app/config/contentful.ts, and base SFCC vendor code, e.g. use-auth-modal.js's and
// otp-auth/index.jsx's getConfig().app.login) throws in Storybook without this. `login: {}` is
// needed alongside `app: {}` — every other getConfig().app.* read in base SFCC guards with `?.`
// or `|| {}`, but otp-auth/index.jsx's `const {tokenLength} = getConfig().app.login` does not,
// so `.login` itself must already be an object. Not a copy of real config values, which have no
// place in a client bundle anyway — just enough shape for vendor code's unguarded reads.
if (typeof window !== 'undefined') {
  (window as typeof window & { __CONFIG__?: { app: Record<string, unknown> } }).__CONFIG__ = {
    app: { login: {} },
  };
}

// ZimmTokensGlobal injects the --zimm-* :root custom properties, mirroring what
// _app-config does in the app. Without it, the .zimm-* global classes and the
// var(--zimm-*) component overrides (button/header/listMenu) render unresolved in
// Storybook. Same shared source as the app, so the two cannot drift.
//
// ZimmFontFace declares the self-hosted Futura Round faces, likewise mirroring
// _app-config. Without it Storybook renders the fallback stack while the app renders
// Futura Round — the fallback measures ~13% wider, so any visual comparison made in
// Storybook would not match the app or Figma. Font files are served here by the
// staticDirs mapping in .storybook/main.js.
const withChakra: Decorator = (Story) => (
  <ChakraProvider theme={theme}>
    <ZimmFontFace />
    <ZimmTokensGlobal />
    <Story />
  </ChakraProvider>
);

const withIntl: Decorator = (Story) => (
  <IntlProvider locale="en-AU" defaultLocale="en-AU">
    <Story />
  </IntlProvider>
);

const preview: Preview = {
  parameters: {
    controls: {
      matchers: {
        color: /(background|color)$/i,
        date: /date$/i,
      },
    },
    layout: 'centered',
    a11y: {
      // 'error' causes a11y violations to fail test-storybook --ci runs
      test: 'error',
      // See a11yExcludes.ts — Storybook's parameters merge is shallow, so a story that sets
      // its own parameters.a11y.context.exclude REPLACES this array rather than extending it;
      // that file's own comment documents how a story adds to it instead.
      context: {
        exclude: CHAKRA_TOAST_A11Y_EXCLUDE,
      },
    },
  },
  decorators: [withChakra, withIntl],
};

export default preview;

// Content styling specific to the HPC-035 name-capture form. Chrome (overlay/panel/actions) is
// shared via zimmModal.css.ts's ZimmModal recipe — see index.tsx for how the two are combined.
export const ZimmSubscribeModal = {
  parts: ['title', 'field', 'fieldLast', 'consent', 'consentLink', 'disclaimer'],
  baseStyle: {
    title: {
      textStyle: 'heading3',
      margin: 0,
      marginBottom: 'var(--zimm-scale-3xl)',
      color: 'var(--zimm-color-text-default)',
    },
    field: { marginBottom: 'var(--zimm-scale-xl)' },
    fieldLast: { marginBottom: 'var(--zimm-scale-3xl)' },
    // Caption-weight consent/disclaimer copy — text.secondary (#666, 5.74:1 on white).
    // text.muted (#969696) would fail WCAG AA 4.5:1 at 12px on the white modal panel.
    consent: {
      textStyle: 'caption',
      margin: 0,
      marginBottom: 'var(--zimm-scale-m)',
      color: 'var(--zimm-color-text-secondary)',
    },
    consentLink: {
      color: 'var(--zimm-color-text-secondary)',
      textDecoration: 'underline',
    },
    disclaimer: {
      textStyle: 'caption',
      margin: 0,
      marginBottom: 'var(--zimm-scale-3xl)',
      color: 'var(--zimm-color-text-secondary)',
    },
  },
};

