import type { SystemStyleObject } from '@chakra-ui/react';

/** State the atom feeds in so the recipe can resolve the Figma state cascade. */
type ZimmSizeChipStyleProps = {
  selected?: boolean;
  disabled?: boolean;
};

/**
 * Border colour precedence: disabled > selected > default — same "no state stacking" shape as
 * zimmTextInput.css.ts's resolveBorderColour. Default and Disabled both resolve to
 * 'transparent' rather than a real colour: Figma's Default/Disabled variants (nodes
 * 40003038:125875 / :125873) render as plain text with no box at all, so the always-present
 * `border` shorthand on `chip` below is made invisible rather than removed outright — the same
 * "transparent border avoids a layout shift" idiom zimmColourSwatch.css.ts's `swatch` part
 * uses for its own unselected state.
 */
export const resolveBorderColour = ({ selected, disabled }: ZimmSizeChipStyleProps): string => {
  if (disabled) return 'transparent'; // Figma Disabled (…125873): no box, muted text only
  if (selected) return 'var(--zimm-color-border-focus)'; // Figma Selected (…125874): outline-only box
  return 'transparent'; // Figma Default (…125875): no box, plain text
};

/**
 * Background is transparent in every branch: Figma's Selected variant (…125874) is an
 * outline-only box — border present, no fill — so no state here ever paints a background.
 * Kept as an explicit disabled/selected/default cascade, matching the other two resolvers'
 * shape, rather than collapsed to a bare `'transparent'` return, so a future Figma revision
 * that does introduce a fill only has to change one branch's value.
 */
export const resolveBackgroundColour = ({ selected, disabled }: ZimmSizeChipStyleProps): string => {
  if (disabled) return 'transparent';
  if (selected) return 'transparent'; // outline-only box — was var(--zimm-color-bg-05); Figma has no fill
  return 'transparent';
};

/**
 * Text colour precedence: disabled > selected > default. Selected does NOT get an inverted
 * (white) treatment — Figma's Selected variant (…125874) keeps the same dark default text
 * colour as Default and only adds the outline box via resolveBorderColour above.
 */
export const resolveTextColour = ({ selected, disabled }: ZimmSizeChipStyleProps): string => {
  if (disabled) return 'var(--zimm-color-text-muted)';
  if (selected) return 'var(--zimm-color-text-default)'; // no inversion — outline-only box, not filled
  return 'var(--zimm-color-text-default)';
};

/**
 * Recipe for the PDP size chip atom — a single 28x28 (--zimm-scale-700) size option, read
 * directly off the size-chip Figma component set (node 40003038:125876) for this exact
 * component's dimensions and state list. Four Figma-defined states — Default / Selected /
 * Focus / Disabled — resolved by the three `resolveXxxColour` helpers above and the
 * `_focusVisible` block below. Hover and Active/pressed are NOT part of that variant set, so
 * neither is implemented here — same "don't invent an unspecified visual state" precedent as
 * zimmColourSwatchGroup.css.ts's `pageButton` part.
 *
 * The STRUCTURE of all four states is directly confirmed against individual Figma PNG exports
 * of each variant (Default …125875, Selected …125874, Disabled …125873, Focus …130506) — not
 * inferred: Default and Disabled render as plain text with no border/box at all; Selected is
 * an outline-only box (border present, no fill — text stays the normal default colour rather
 * than inverting); Focus is Selected's border box plus an additional outer ring (confirmed by
 * its 34x34 Figma frame vs. 28x28 for the other three — the ring extends past the chip
 * itself). Only the exact border/text COLOUR TOKEN choice (`--zimm-color-border-focus` /
 * `--zimm-color-text-default` / `--zimm-color-text-muted`) remains this file's own inference
 * from precedent rather than a pixel-confirmed hex breakdown — flag for UI-designer
 * confirmation if a token choice doesn't match.
 */
export const ZimmSizeChip = {
  parts: ['chip'],
  baseStyle: (props: ZimmSizeChipStyleProps): Record<string, SystemStyleObject> => ({
    chip: {
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      width: 'var(--zimm-scale-700)', // 28px
      height: 'var(--zimm-scale-700)', // 28px
      // Width/style stay constant across every state; only borderColor toggles between
      // 'transparent' (Default/Disabled — no visible box) and a real token (Selected) — see
      // resolveBorderColour above.
      border: 'var(--zimm-border-width-default) solid',
      borderColor: resolveBorderColour(props),
      background: resolveBackgroundColour(props),
      color: resolveTextColour(props),
      textStyle: 'buttonSm',
      padding: 0,
      outline: 'none',
      cursor: props.disabled ? 'not-allowed' : 'pointer',
      _focusVisible: {
        // Figma's Focus variant (…130506) shows a border box even when the chip isn't
        // selected, so focus-visible applies the same border colour Selected uses, on top of
        // (not instead of) the outer ring — an unselected-but-tabbed-to chip still gets a
